import type { Report } from './types.js';
import { GROUPS, ALL_FIELDS, ALL_NUMERIC_KEYS, MONTHS } from './constants.js';
import { state } from './state.js';
import { pad, parseISO, monthKeyOf, weekday } from './dateUtils.js';
import { num, numOrNull, informed } from './format.js';
import { metaFor, metaDiaVal, aprovadasNoMes, monthTotals, weeklyBreakdown, metaPJFor } from './aggregations.js';
import { toast } from './ui.js';

/* ---------------- PDF generation (no external library) ---------------- */
// Colors (0-1) used in the PDF
type RGB01 = [number, number, number];
const PDF = {
  RED: [0.91, 0.45, 0.31] as RGB01, WHITE: [1, 1, 1] as RGB01, INK: [0.11, 0.11, 0.14] as RGB01,
  MUTED: [0.42, 0.45, 0.50] as RGB01, LIGHT: [0.88, 0.89, 0.91] as RGB01, GREEN: [0.12, 0.62, 0.34] as RGB01,
  BLUE: [0.114, 0.475, 0.780] as RGB01, BLUE_DARK: [0.055, 0.318, 0.573] as RGB01,
};
function pdfEsc(s: any): string { return String(s).replace(/\\/g, '\\\\').replace(/\(/g, '\\(').replace(/\)/g, '\\)'); }
function latin1(s: any): string { return String(s).replace(/[^\x00-\xFF]/g, ''); } // strip anything that isn't Latin-1 (e.g. emoji)

// Standard AFM glyph widths (per 1000 em) for Helvetica/Helvetica-Bold — only the characters
// actually used in text we need to CENTER (digits, %, space, A-Z). Without these, centering can
// only guess an average char width, which visibly drifts off-center (this is the alignment bug
// that got reported). Anything not listed falls back to 556 (a digit's width, a safe average).
const HELV_W: Record<string, number> = { ' ': 278, '%': 889,
  '0': 556, '1': 556, '2': 556, '3': 556, '4': 556, '5': 556, '6': 556, '7': 556, '8': 556, '9': 556,
  A: 667, B: 667, C: 722, D: 722, E: 667, F: 611, G: 778, H: 722, I: 278, J: 500, K: 667, L: 556,
  M: 833, N: 722, O: 778, P: 667, Q: 778, R: 722, S: 667, T: 611, U: 722, V: 667, W: 944, X: 667, Y: 667, Z: 611 };
const HELV_BOLD_W: Record<string, number> = { ' ': 278, '%': 1000,
  '0': 556, '1': 556, '2': 556, '3': 556, '4': 556, '5': 556, '6': 556, '7': 556, '8': 556, '9': 556,
  A: 722, B: 722, C: 722, D: 722, E: 667, F: 611, G: 778, H: 722, I: 278, J: 500, K: 722, L: 611,
  M: 889, N: 722, O: 778, P: 667, Q: 778, R: 722, S: 667, T: 611, U: 722, V: 667, W: 944, X: 667, Y: 667, Z: 611 };
function textWidth(s: string, font: string, size: number): number {
  const table = font === 'F2' ? HELV_BOLD_W : HELV_W;
  let w = 0;
  for (const ch of String(s).toUpperCase()) w += table[ch] ?? 556;
  return (w / 1000) * size;
}
// Lightens a color toward white — used for the pastel badge behind each field icon.
function tint(c: RGB01, amt = 0.82): RGB01 {
  return [c[0] + (1 - c[0]) * amt, c[1] + (1 - c[1]) * amt, c[2] + (1 - c[2]) * amt];
}

// Accent color per field (mirrors the meaning already used elsewhere: green/red/amber for
// the proposal outcomes). Anything not listed falls back to the brand red.
const FIELD_COLOR: Record<string, RGB01> = {
  aprovadas: [0.047, 0.639, 0.047],
  reprovadas: [0.816, 0.231, 0.231],
  analise: [0.788, 0.522, 0.000],
  link: [0.117, 0.443, 0.831],
  cartaoAtivacao: [0.722, 0.525, 0.043],
  sms: [0.290, 0.333, 0.412],
  bonus: [0.831, 0.400, 0.055],
  odontoEfetivado: [0.043, 0.588, 0.502],
  odontoOfertado: [0.702, 0.169, 0.169],
};
const CARD_BG: RGB01 = [1, 1, 1];
const PAGE_BG: RGB01 = [0.957, 0.961, 0.969];
// Field icons (48x48 raster, extracted from a real color-emoji render — the standard
// PDF fonts have zero pictographic glyphs, so this is the only way to show a real-looking
// icon instead of emoji text (which silently disappears — see latin1() above). Each icon is
// embedded as a DeviceRGB Image XObject with a DeviceGray SMask for transparency.
const ICON_SIZE = 48;
const ICON_ORDER = ["aprovadas","reprovadas","analise","link","cartaoAtivacao","sms","bonus","odontoEfetivado","odontoOfertado"] as const;
type IconKey = typeof ICON_ORDER[number];
const ICON_RGB_B64: Record<IconKey, string> = {
  aprovadas: '',
  reprovadas: '',
  analise: '',
  link: '',
  cartaoAtivacao: '',
  sms: '',
  bonus: '',
  odontoEfetivado: '',
  odontoOfertado: '',
};
const ICON_ALPHA_B64: Record<IconKey, string> = {
  aprovadas: '',
  reprovadas: '',
  analise: '',
  link: '',
  cartaoAtivacao: '',
  sms: '',
  bonus: '',
  odontoEfetivado: '',
  odontoOfertado: '',
};


function buildReportPDF(r: Report): Blob {
  const d = parseISO(r.data);
  const mk = monthKeyOf(r.data);
  const meta = metaFor(mk);
  const feitas = aprovadasNoMes(mk);
  const pct = meta > 0 ? Math.round((feitas / meta) * 100) : 0;

  return pdfBuild(({ txt, rect, line, roundedRect, dot, image, F1, F2 }) => {
  // Page background (the white cards need something other than white to stand out against).
  rect(0, 0, 595, 792, PAGE_BG);
  // Red header band
  rect(0, 792, 595, 50, PDF.RED);
  txt(40, 814, 19, F2, PDF.WHITE, 'RELATÓRIO DIÁRIO');
  txt(40, 799, 10.5, F1, PDF.WHITE, (r.loja || 'Savegnago') + '   ·   ' + (r.promotora || ''));

  let y = 752;
  // Date
  const dataFmt = pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear();
  txt(40, y, 10, F1, PDF.MUTED, 'DATA');
  txt(40, y - 17, 15, F2, PDF.INK, dataFmt + '   ·   ' + weekday(d));
  y -= 44;

  const sectionTitle = (title: string) => { txt(40, y, 10.5, F2, PDF.RED, title.toUpperCase()); y -= 18; };

  const COLS = 3, GAP = 8, CARD_W = (515 - GAP * (COLS - 1)) / COLS, CARD_H = 54;
  // Draws one row of up to COLS cards, advancing y past ALL rows needed for `fields`.
  const cardsGrid = (fields: { label: string; value: any; key: IconKey }[]) => {
    for (let i = 0; i < fields.length; i += COLS) {
      const rowFields = fields.slice(i, i + COLS);
      rowFields.forEach((f, col) => {
        const x = 40 + col * (CARD_W + GAP);
        const fc = FIELD_COLOR[f.key] || PDF.RED;
        roundedRect(x, y - CARD_H, CARD_W, CARD_H, 8, CARD_BG);
        roundedRect(x + 10, y - 32, 22, 22, 6, tint(fc));
        image(f.key, x + 14, y - 28, 14, 14);
        txt(x + 40, y - 28, 19, F2, PDF.INK, String(f.value));
        txt(x + 10, y - 44, 8.5, F1, fc, f.label.toUpperCase());
      });
      y -= CARD_H + GAP;
    }
  };

  // Sections come from GROUPS: any new field is picked up automatically. Not informed = 0
  // (a field left blank on a single day means "didn't happen today", not "unknown").
  GROUPS.forEach(g => {
    sectionTitle(g.title);
    cardsGrid(g.fields.map(f => ({ label: f.label, value: num(r[f.key]), key: f.key as IconKey })));
    y -= 8;
  });

  // Cartão PJ — só quando o relatório tem algum número PJ. Reaproveita os ícones de
  // aprovadas / em análise (PJ não tem ícone próprio).
  if (informed(r.pjAprovadas) || informed(r.pjAnalise)) {
    sectionTitle('Cartão PJ');
    cardsGrid([
      { label: 'PJ Aprovadas', value: num(r.pjAprovadas), key: 'aprovadas' as IconKey },
      { label: 'PJ Em Análise', value: num(r.pjAnalise), key: 'analise' as IconKey },
    ]);
    y -= 8;
  }

  // Goals — same card treatment, wider (2 cols) since the values are fraction-shaped.
  sectionTitle('Metas');
  const md = metaDiaVal();
  const metaCards = [
    { label: 'Meta do dia', value: num(r.aprovadas) + ' / ' + md + (num(r.aprovadas) >= md ? ' (bateu)' : ''), color: PDF.GREEN },
    { label: 'Meta do mês', value: feitas + ' / ' + (meta || 0) + (meta ? ' (' + pct + '%)' : ''), color: PDF.RED },
  ];
  if (state.config.metaPJAtiva) {
    const metaPJ = metaPJFor(mk);
    const feitasPJ = monthTotals(mk).pjAprovadas as number || 0;
    metaCards.push({
      label: 'Meta do mês · PJ',
      value: feitasPJ + ' / ' + (metaPJ || 0) + (metaPJ ? ' (' + Math.round((feitasPJ / metaPJ) * 100) + '%)' : ''),
      color: PDF.BLUE,
    });
  }
  const MGAP = 8, MCARD_W = (515 - MGAP) / 2, MCARD_H = 54;
  metaCards.forEach((f, i) => {
    const col = i % 2, row = Math.floor(i / 2);
    const x = 40 + col * (MCARD_W + MGAP);
    const cy = y - row * (MCARD_H + MGAP);
    roundedRect(x, cy - MCARD_H, MCARD_W, MCARD_H, 8, CARD_BG);
    dot(x + 15, cy - 14, 4, f.color);
    txt(x + 12, cy - 34, 16, F2, PDF.INK, String(f.value));
    txt(x + 12, cy - 47, 8.5, F1, PDF.MUTED, f.label.toUpperCase());
  });
  y -= Math.ceil(metaCards.length / 2) * (MCARD_H + MGAP) + 8;

  // Notes (with simple line wrapping), on its own light card.
  if (r.obs && String(r.obs).trim()) {
    sectionTitle('Observações');
    const words = String(r.obs).replace(/\s+/g, ' ').trim().split(' ');
    const lines: string[] = [];
    let ln = '';
    words.forEach((w: string) => {
      if ((ln + ' ' + w).length > 85) { lines.push(ln); ln = ''; }
      ln = ln ? ln + ' ' + w : w;
    });
    if (ln) lines.push(ln);
    const boxH = lines.length * 16 + 16;
    roundedRect(40, y - boxH, 515, boxH, 8, CARD_BG);
    let ly = y - 20;
    lines.forEach(l => { txt(52, ly, 11, F1, PDF.INK, l); ly -= 16; });
    y -= boxH;
  }

  // Footer
  line(40, 30, 555, PDF.LIGHT);
  let quando = '';
  try { quando = new Date().toLocaleString('pt-BR'); } catch (e) {}
  txt(40, 18, 9, F1, PDF.MUTED, 'Gerado em ' + quando + '  ·  App Relatório Diário');
  });
}

function assemblePdf(c: string): Blob {
  // Object numbers 1-6 are fixed (catalog/pages/page/contents/F1/F2); each icon adds two more
  // (an alpha SMask object, then the RGB image object that references it) starting at 7.
  const xobjRefs: string[] = [];
  const imageObjs: string[] = [];
  let nextNum = 7;
  ICON_ORDER.forEach(key => {
    const alphaBin = atob(ICON_ALPHA_B64[key]);
    const rgbBin = atob(ICON_RGB_B64[key]);
    const alphaNum = nextNum++;
    const rgbNum = nextNum++;
    imageObjs.push(`<< /Type /XObject /Subtype /Image /Width ${ICON_SIZE} /Height ${ICON_SIZE} /ColorSpace /DeviceGray /BitsPerComponent 8 /Length ${alphaBin.length} >>\nstream\n${alphaBin}\nendstream`);
    imageObjs.push(`<< /Type /XObject /Subtype /Image /Width ${ICON_SIZE} /Height ${ICON_SIZE} /ColorSpace /DeviceRGB /BitsPerComponent 8 /SMask ${alphaNum} 0 R /Length ${rgbBin.length} >>\nstream\n${rgbBin}\nendstream`);
    xobjRefs.push(`/Ic_${key} ${rgbNum} 0 R`);
  });

  const objs = [
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 5 0 R /F2 6 0 R >> /XObject << ' + xobjRefs.join(' ') + ' >> >> /Contents 4 0 R >>',
    '<< /Length ' + c.length + ' >>\nstream\n' + c + 'endstream',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>',
    '<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>',
    ...imageObjs,
  ];
  let pdf = '%PDF-1.4\n';
  const offsets: number[] = [];
  objs.forEach((o, i) => { offsets.push(pdf.length); pdf += (i + 1) + ' 0 obj\n' + o + '\nendobj\n'; });
  const xref = pdf.length;
  pdf += 'xref\n0 ' + (objs.length + 1) + '\n0000000000 65535 f \n';
  offsets.forEach(off => { pdf += String(off).padStart(10, '0') + ' 00000 n \n'; });
  pdf += 'trailer\n<< /Size ' + (objs.length + 1) + ' /Root 1 0 R >>\nstartxref\n' + xref + '\n%%EOF';

  const bytes = new Uint8Array(pdf.length);
  for (let i = 0; i < pdf.length; i++) bytes[i] = pdf.charCodeAt(i) & 0xff;
  return new Blob([bytes], { type: 'application/pdf' });
}

export function sharePDF(r: Report | null) {
  if (!r || !r.data) { toast('Nenhum relatório para gerar PDF', 'err'); return; }
  ALL_NUMERIC_KEYS.forEach(k => (r as any)[k] = numOrNull((r as any)[k]));
  const blob = buildReportPDF(r);
  const primeiroNome = (r.promotora || 'Edna').split(' ')[0];
  const fname = 'Relatorio_' + r.data + '_' + primeiroNome + '.pdf';
  downloadOrShare(blob, fname, 'application/pdf');
}

// Assembles an A4 PDF from a drawing function — reused by both the report and the summary.
function pdfBuild(draw: (helpers: {
  txt: (x: number, y: number, size: number, font: string, color: RGB01, s: any) => void;
  rect: (x: number, y: number, w: number, h: number, color: RGB01) => void;
  line: (x1: number, y: number, x2: number, color: RGB01) => void;
  sector: (cx: number, cy: number, R: number, a0: number, a1: number, color: RGB01) => void;
  roundedRect: (x: number, y: number, w: number, h: number, r: number, color: RGB01) => void;
  dot: (cx: number, cy: number, R: number, color: RGB01) => void;
  image: (key: IconKey, x: number, y: number, w: number, h: number) => void;
  centerText: (cx: number, y: number, size: number, font: string, color: RGB01, s: any) => void;
  F1: string; F2: string;
}) => void): Blob {
  let c = '';
  const F1 = 'F1', F2 = 'F2';
  const txt = (x: number, y: number, size: number, font: string, color: RGB01, s: any) => { const [r, g, b] = color; c += `BT /${font} ${size} Tf ${r} ${g} ${b} rg ${x} ${y} Td (${pdfEsc(latin1(s))}) Tj ET\n`; };
  const rect = (x: number, y: number, w: number, h: number, color: RGB01) => { const [r, g, b] = color; c += `${r} ${g} ${b} rg ${x} ${y} ${w} ${h} re f\n`; };
  const line = (x1: number, y: number, x2: number, color: RGB01) => { const [r, g, b] = color; c += `${r} ${g} ${b} RG 0.6 w ${x1} ${y} m ${x2} ${y} l S\n`; };
  // Rounded card background — 4 straight edges + 4 Bézier corner arcs (k ≈ 0.5523 * r).
  const roundedRect = (x: number, y: number, w: number, h: number, r: number, color: RGB01) => {
    const [rr, gg, bb] = color, k = 0.5523 * r;
    c += `${rr} ${gg} ${bb} rg `
      + `${x + r} ${y} m ${x + w - r} ${y} l `
      + `${x + w - r + k} ${y} ${x + w} ${y + r - k} ${x + w} ${y + r} c ${x + w} ${y + h - r} l `
      + `${x + w} ${y + h - r + k} ${x + w - r + k} ${y + h} ${x + w - r} ${y + h} c ${x + r} ${y + h} l `
      + `${x + r - k} ${y + h} ${x} ${y + h - r + k} ${x} ${y + h - r} c ${x} ${y + r} l `
      + `${x} ${y + r - k} ${x + r - k} ${y} ${x + r} ${y} c f\n`;
  };
  // Filled dot — 4 Bézier quarter-arcs around the center (same k constant as roundedRect).
  const dot = (cx: number, cy: number, R: number, color: RGB01) => {
    const [rr, gg, bb] = color, k = 0.5523 * R;
    c += `${rr} ${gg} ${bb} rg `
      + `${cx + R} ${cy} m ${cx + R} ${cy + k} ${cx + k} ${cy + R} ${cx} ${cy + R} c `
      + `${cx - k} ${cy + R} ${cx - R} ${cy + k} ${cx - R} ${cy} c `
      + `${cx - R} ${cy - k} ${cx - k} ${cy - R} ${cx} ${cy - R} c `
      + `${cx + k} ${cy - R} ${cx + R} ${cy - k} ${cx + R} ${cy} c f\n`;
  };
  // Filled pie sector (a0/a1 in radians, CCW). Approximates the arc with Béziers.
  const sector = (cx: number, cy: number, R: number, a0: number, a1: number, color: RGB01) => {
    const [r, g, b] = color;
    let s = `${r} ${g} ${b} rg ${cx} ${cy} m ${cx + R * Math.cos(a0)} ${cy + R * Math.sin(a0)} l `;
    let start = a0;
    const dir = a1 >= a0 ? 1 : -1;
    while (Math.abs(a1 - start) > 1e-6) {
      const step = dir * Math.min(Math.PI / 2, Math.abs(a1 - start));
      const end = start + step;
      const k = (4 / 3) * Math.tan(step / 4);
      const p0x = cx + R * Math.cos(start), p0y = cy + R * Math.sin(start);
      const c1x = p0x - k * R * Math.sin(start), c1y = p0y + k * R * Math.cos(start);
      const p1x = cx + R * Math.cos(end), p1y = cy + R * Math.sin(end);
      const c2x = p1x + k * R * Math.sin(end), c2y = p1y - k * R * Math.cos(end);
      s += `${c1x} ${c1y} ${c2x} ${c2y} ${p1x} ${p1y} c `;
      start = end;
    }
    c += s + `${cx} ${cy} l f\n`;
  };
  // Places an embedded icon image (see ICON_RGB_B64) in the [x,y]..[x+w,y+h] box.
  const image = (key: IconKey, x: number, y: number, w: number, h: number) => {
    c += `q ${w} 0 0 ${h} ${x} ${y} cm /Ic_${key} Do Q\n`;
  };
  // Horizontally centers `s` on `cx` using real glyph widths (see textWidth) — plain
  // char-count guessing is what caused the donut/label centering to visibly drift off-center.
  const centerText = (cx: number, y: number, size: number, font: string, color: RGB01, s: any) => {
    txt(cx - textWidth(String(s), font, size) / 2, y, size, font, color, s);
  };
  draw({ txt, rect, line, sector, roundedRect, dot, image, centerText, F1, F2 });
  return assemblePdf(c);
}

function buildMonthPDF(monthKey: string): Blob {
  const [y, m] = monthKey.split('-').map(Number);
  const t = monthTotals(monthKey);
  const meta = metaFor(monthKey);
  const pct = meta > 0 ? Math.round(((t.aprovadas || 0) / meta) * 100) : 0;
  const weeks = weeklyBreakdown(monthKey);
  const PIE = [
    { label: 'Aprovadas', value: t.aprovadas || 0, color: [0.047, 0.639, 0.047] as RGB01 },
    { label: 'Reprovadas', value: t.reprovadas || 0, color: [0.816, 0.231, 0.231] as RGB01 },
    { label: 'Em Análise', value: t.analise || 0, color: [0.788, 0.522, 0.000] as RGB01 },
  ];
  const pieTotal = PIE.reduce((s, x) => s + (x.value as number), 0);

  return pdfBuild(({ txt, rect, line, sector, roundedRect, dot, image, centerText, F1, F2 }) => {
    let yy = 752;
    rect(0, 0, 595, 792, PAGE_BG);
    rect(0, 792, 595, 50, PDF.RED);
    txt(40, 814, 19, F2, PDF.WHITE, 'RESUMO DO MÊS');
    txt(40, 799, 10.5, F1, PDF.WHITE, (state.config.loja || '') + '  ·  ' + (state.config.promotora || ''));
    txt(40, yy, 10, F1, PDF.MUTED, 'MÊS');
    txt(40, yy - 17, 15, F2, PDF.INK, MONTHS[m - 1] + ' ' + y + '   ·   ' + t._dias + ' dia(s) com relatório');
    yy -= 44;

    const sectionTitle = (title: string) => { txt(40, yy, 10.5, F2, PDF.RED, title.toUpperCase()); yy -= 18; };

    // META — big colored hero card with a fraction, a % pill and a progress bar.
    const metaH = 76;
    roundedRect(40, yy - metaH, 515, metaH, 14, PDF.BLUE);
    txt(58, yy - 24, 9.5, F2, PDF.WHITE, 'META DO MÊS · APROVADOS');
    txt(58, yy - 50, 24, F2, PDF.WHITE, (t.aprovadas || 0) + ' / ' + (meta || 0));
    const pillW = 58, pillH = 24, pillX = 40 + 515 - 20 - pillW, pillY = yy - 20 - pillH;
    roundedRect(pillX, pillY, pillW, pillH, 12, PDF.WHITE);
    centerText(pillX + pillW / 2, pillY + 7.5, 11.5, F2, PDF.BLUE_DARK, pct + '%');
    const barX = 58, barW = 515 - 36, barY = yy - metaH + 14;
    roundedRect(barX, barY, barW, 6, 3, PDF.BLUE_DARK);
    const fillW = meta > 0 ? Math.max(0, barW * Math.min(1, pct / 100)) : 0;
    if (fillW > 7) roundedRect(barX, barY, fillW, 6, 3, PDF.WHITE);
    yy -= metaH + 24;

    // PROPOSTAS — donut with a hole (Bézier circle drawn over the wedges) + centered total,
    // legend to the right. All inside a white card, like the app's panel.
    sectionTitle('Propostas');
    const propCardH = 136;
    roundedRect(40, yy - propCardH, 515, propCardH, 14, CARD_BG);
    const cx = 40 + 80, cy = yy - propCardH / 2, R = 50, holeR = 30;
    if (pieTotal <= 0) {
      sector(cx, cy, R, 0, 2 * Math.PI - 1e-4, PDF.LIGHT);
    } else {
      let a = Math.PI / 2; // starts at the top
      PIE.forEach(s => {
        if ((s.value as number) <= 0) return;
        const a1 = a + ((s.value as number) / pieTotal) * 2 * Math.PI;
        sector(cx, cy, R, a, a1, s.color);
        a = a1;
      });
    }
    dot(cx, cy, holeR, CARD_BG);
    centerText(cx, cy - 5, 18, F2, PDF.INK, String(pieTotal));
    centerText(cx, cy - 19, 7, F1, PDF.MUTED, 'PROPOSTAS');
    let ly = yy - 40;
    PIE.forEach(s => {
      dot(40 + 180, ly + 3.5, 4.5, s.color);
      txt(40 + 192, ly, 11, F1, PDF.INK, s.label);
      txt(40 + 430, ly, 11, F2, PDF.INK, s.value + (pieTotal ? '  (' + Math.round(((s.value as number) / pieTotal) * 100) + '%)' : ''));
      ly -= 23;
    });
    yy -= propCardH + 24;

    // CARTÃO PJ — só quando a métrica está ligada. Dois cards (Aprovadas / Em Análise)
    // mais a linha da meta PJ do mês.
    if (state.config.metaPJAtiva) {
      sectionTitle('Cartão PJ');
      const metaPJ = metaPJFor(monthKey);
      const feitasPJ = (t.pjAprovadas as number) || 0;
      const pctPJ = metaPJ > 0 ? Math.round((feitasPJ / metaPJ) * 100) : 0;
      const pjCards = [
        { label: 'PJ Aprovadas', value: num(t.pjAprovadas), key: 'aprovadas' as IconKey },
        { label: 'PJ Em Análise', value: num(t.pjAnalise), key: 'analise' as IconKey },
      ];
      const PJGAP = 6, PJ_W = (515 - PJGAP) / 2, PJ_H = 52;
      pjCards.forEach((f, col) => {
        const x = 40 + col * (PJ_W + PJGAP);
        const fc = FIELD_COLOR[f.key] || PDF.RED;
        roundedRect(x, yy - PJ_H, PJ_W, PJ_H, 8, CARD_BG);
        roundedRect(x + 10, yy - 32, 22, 22, 6, tint(fc));
        image(f.key, x + 14, yy - 28, 14, 14);
        txt(x + 40, yy - 28, 19, F2, PDF.INK, String(f.value));
        txt(x + 10, yy - 42, 8, F1, fc, f.label.toUpperCase());
      });
      yy -= PJ_H + 10;
      txt(40, yy, 10, F1, PDF.MUTED,
        'META PJ:  ' + feitasPJ + ' / ' + (metaPJ || 0) + (metaPJ ? '   (' + pctPJ + '%)' : ''));
      yy -= 24;
    }

    // TOTAIS DO MÊS — same rounded-card grid as the daily report PDF: icon on a pastel badge
    // of its own color, the number beside it (not stacked), label below in that same color.
    sectionTitle('Totais do mês');
    const COLS = 3, GAP = 6, CARD_W = (515 - GAP * (COLS - 1)) / COLS, CARD_H = 52;
    for (let i = 0; i < ALL_FIELDS.length; i += COLS) {
      const rowFields = ALL_FIELDS.slice(i, i + COLS);
      rowFields.forEach((f, col) => {
        const x = 40 + col * (CARD_W + GAP);
        const fc = FIELD_COLOR[f.key] || PDF.RED;
        roundedRect(x, yy - CARD_H, CARD_W, CARD_H, 8, CARD_BG);
        roundedRect(x + 10, yy - 32, 22, 22, 6, tint(fc));
        image(f.key as IconKey, x + 14, yy - 28, 14, 14);
        txt(x + 40, yy - 28, 19, F2, PDF.INK, String(num(t[f.key])));
        txt(x + 10, yy - 42, 8, F1, fc, f.label.toUpperCase());
      });
      yy -= CARD_H + GAP;
    }
    yy -= 18;

    // POR SEMANA — one compact line + a thin progress bar per week, relative to the month's
    // best week (keeps each week to ~20pt so a 5-week month still fits on one page).
    if (weeks.length) {
      sectionTitle('Por semana');
      const maxAp = Math.max(1, ...weeks.map(w => w.aprovadas));
      weeks.forEach(w => {
        const d = parseISO(w.week);
        const label = 'Semana ' + pad(d.getDate()) + '/' + pad(d.getMonth() + 1)
          + '   ·   ' + w.dias + ' dia(s)   ·   ' + w.reprovadas + ' reprov.';
        txt(40, yy, 10, F1, PDF.INK, label);
        txt(490, yy, 11, F2, PDF.INK, w.aprovadas + ' aprov.');
        yy -= 10;
        roundedRect(40, yy - 5, 515, 5, 2.5, PDF.LIGHT);
        const fw = Math.max(0, 515 * (w.aprovadas / maxAp));
        if (fw > 5) roundedRect(40, yy - 5, fw, 5, 2.5, PDF.GREEN);
        yy -= 15;
      });
    }

    line(40, 30, 555, PDF.LIGHT);
    let quando = ''; try { quando = new Date().toLocaleString('pt-BR'); } catch (e) {}
    txt(40, 18, 9, F1, PDF.MUTED, 'Gerado em ' + quando + '  ·  App Relatório Diário');
  });
}

export function shareMonthPDF(monthKey: string) {
  const blob = buildMonthPDF(monthKey);
  downloadOrShare(blob, 'Resumo_' + monthKey + '.pdf', 'application/pdf');
}

export function downloadOrShare(blob: Blob, fname: string, mime: string) {
  try {
    const file = new File([blob], fname, { type: mime });
    if ((navigator as any).canShare && (navigator as any).canShare({ files: [file] })) {
      // If sharing fails (e.g. no user gesture) or is cancelled → download the file instead.
      (navigator as any).share({ files: [file], title: fname })
        .catch(() => baixarArquivo(blob, fname));
      return;
    }
  } catch (e) { /* cai no download abaixo */ }
  baixarArquivo(blob, fname);
}

export function baixarArquivo(blob: Blob, fname: string) {
  try {
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = fname;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(() => URL.revokeObjectURL(url), 15000);
    toast('Salvo em Downloads: ' + fname, 'ok');
  } catch (e) {
    toast('Não foi possível salvar o arquivo', 'err');
  }
}
